@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h3>Notepad</h3>

<textarea @bind="content" @bind:event="oninput" rows="15" style="width:100%;" placeholder="Type your notes here..."></textarea>

<div style="margin-top: 0.5rem; display: flex; align-items: center; gap: 1rem;">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-danger" @onclick="Clear">Clear</button>
    @if (lastSaved.HasValue)
    {
        <span>Last saved at @lastSaved.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSaved;
    private System.Threading.Timer? autoSaveTimer;
    private IJSObjectReference? module;
    private DotNetObjectReference<Notepad>? dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Notepad.razor.js");
            dotNetRef = DotNetObjectReference.Create(this);

            var stored = await module.InvokeAsync<string?>("load");
            if (!string.IsNullOrEmpty(stored))
            {
                content = stored;
                savedContent = stored;
                StateHasChanged();
            }

            await module.InvokeVoidAsync("registerBeforeUnload", dotNetRef);

            autoSaveTimer = new System.Threading.Timer(async _ =>
            {
                await InvokeAsync(async () =>
                {
                    if (content != savedContent)
                    {
                        await Save();
                        StateHasChanged();
                    }
                });
            }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async Task SaveNow()
    {
        await Save();
    }

    private async Task Save()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("save", content);
            savedContent = content;
            lastSaved = DateTime.Now;
        }
    }

    private async Task Clear()
    {
        content = string.Empty;
        savedContent = string.Empty;
        lastSaved = null;
        if (module is not null)
        {
            await module.InvokeVoidAsync("clear");
        }
    }

    [JSInvokable]
    public bool HasUnsavedChanges() => content != savedContent;

    public async ValueTask DisposeAsync()
    {
        autoSaveTimer?.Dispose();
        if (module is not null)
        {
            await module.InvokeVoidAsync("unregisterBeforeUnload");
            await module.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}

const STORAGE_KEY = "notepad-content";
let dotNetRef = null;
let beforeUnloadHandler = null;

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function registerBeforeUnload(ref) {
    dotNetRef = ref;
    beforeUnloadHandler = (e) => {
        if (dotNetRef) {
            // Synchronous check isn't possible with async JS interop,
            // so we use a flag kept in sync via the handler approach below.
        }
        e.preventDefault();
        e.returnValue = "";
    };

    // We use a proxy handler that always triggers the dialog;
    // the component only registers this when there could be unsaved changes.
    window.addEventListener("beforeunload", onBeforeUnload);
}

export function unregisterBeforeUnload() {
    window.removeEventListener("beforeunload", onBeforeUnload);
    dotNetRef = null;
}

function onBeforeUnload(e) {
    // The browser will show the confirmation dialog whenever this handler
    // calls preventDefault. We rely on the component always registering this
    // only while it's active — the JS interop call to check unsaved state
    // can't be done synchronously, so we optimistically prevent unload and
    // let the browser decide (content typed = unsaved likely).
    // A more precise approach: keep a JS-side dirty flag in sync.
    if (isDirty) {
        e.preventDefault();
        e.returnValue = "";
    }
}

let isDirty = false;

export function setDirty(dirty) {
    isDirty = dirty;
}

