const STORAGE_KEY = "notepad-content";
let dotNetRef = null;
let beforeUnloadHandler = null;

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function registerBeforeUnload(ref) {
    dotNetRef = ref;
    beforeUnloadHandler = (e) => {
        if (dotNetRef) {
            // Synchronous check isn't possible with async JS interop,
            // so we use a flag kept in sync via the handler approach below.
        }
        e.preventDefault();
        e.returnValue = "";
    };

    // We use a proxy handler that always triggers the dialog;
    // the component only registers this when there could be unsaved changes.
    window.addEventListener("beforeunload", onBeforeUnload);
}

export function unregisterBeforeUnload() {
    window.removeEventListener("beforeunload", onBeforeUnload);
    dotNetRef = null;
}

function onBeforeUnload(e) {
    // The browser will show the confirmation dialog whenever this handler
    // calls preventDefault. We rely on the component always registering this
    // only while it's active — the JS interop call to check unsaved state
    // can't be done synchronously, so we optimistically prevent unload and
    // let the browser decide (content typed = unsaved likely).
    // A more precise approach: keep a JS-side dirty flag in sync.
    if (isDirty) {
        e.preventDefault();
        e.returnValue = "";
    }
}

let isDirty = false;

export function setDirty(dirty) {
    isDirty = dirty;
}

